ll ksm(ll a,int b){ll res=1;while(b){if(b&1)res=res*a%MOD;a=a*a%MOD,b>>=1;}return res;} 
ll calc(){
	ll ans=1;
	for(int i=1;i<=k;i++) ans=ans*(w[i]-le[i]-ri[i])%MOD;
	return ans;
}
bool allend(){
	for(int i=1;i<=k;i++) if(le[i]+ri[i]>=w[i]) return true;
	return false;
}
bool notend(){
