ll laug(int n,ll x){
	ll sum=0;
	for(int i=0;i<=n;i++){
		ll res=val[i];
		for(int j=0;j<=n;j++) if(i!=j)
			res=res*(x-j+MOD)%MOD*ksm(i-j+MOD,MOD-2)%MOD;
		sum+=res;
	}
	return sum%MOD;
}
